"""Netscape cookie file parsing, serialization, browser extraction, and storage."""

import re
import uuid
from pathlib import Path

from ..core.config import default_config
from ..core.logging import get_logger
from .models import CookieEntry, CookieProfileRecord

logger = get_logger("auth.cookies")

NETSCAPE_HEADER = (
    "# Netscape HTTP Cookie File\n"
    "# https://curl.se/docs/http-cookies.html\n"
    "# This file was generated by XakuMedia.\n\n"
)

SUPPORTED_BROWSERS = ["chrome", "edge", "firefox", "brave", "opera", "vivaldi"]


def parse_netscape_cookies(content: str) -> list[CookieEntry]:
    """Parse raw Netscape HTTP cookie file format text into a list of CookieEntry models.

    Handles #HttpOnly_ prefixes and skips blank or comment lines.
    """
    cookies: list[CookieEntry] = []
    lines = content.splitlines()

    for line_num, raw_line in enumerate(lines, start=1):
        line = raw_line.strip()
        if not line:
            continue

        # Handle #HttpOnly_ prefix standard
        if line.startswith("#HttpOnly_"):
            line = line[len("#HttpOnly_") :]
        elif line.startswith("#"):
            continue

        parts = line.split("\t")
        if len(parts) < 7:
            # Fallback for space-separated if tab was replaced
            parts = re.split(r"\s+", line, maxsplit=6)

        if len(parts) < 7:
            logger.debug(f"Skipping malformed cookie line {line_num}: {line}")
            continue

        domain = parts[0].strip()
        flag = parts[1].strip().upper() == "TRUE"
        path = parts[2].strip() or "/"
        secure = parts[3].strip().upper() == "TRUE"
        try:
            expiration = int(parts[4].strip())
        except ValueError:
            expiration = 0

        name = parts[5].strip()
        value = parts[6].strip()

        if not domain or not name:
            continue

        cookies.append(
            CookieEntry(
                domain=domain,
                flag=flag,
                path=path,
                secure=secure,
                expiration=expiration,
                name=name,
                value=value,
            )
        )

    return cookies


def format_netscape_cookies(cookies: list[CookieEntry]) -> str:
    """Serialize a list of CookieEntry models into standard Netscape format text."""
    lines = [NETSCAPE_HEADER]
    for c in cookies:
        lines.append(c.to_netscape_line() + "\n")
    return "".join(lines)


def sanitize_domain_for_filename(domain: str) -> str:
    """Sanitize domain string for safe filename generation."""
    clean = re.sub(r"[^\w\-.]", "_", domain.lower().lstrip("."))
    return clean or "cookie"


def save_cookies_text(
    domain: str,
    content: str,
    browser_source: str | None = None,
    cookies_dir: Path | None = None,
) -> tuple[CookieProfileRecord, list[CookieEntry]]:
    """Parse, format, and save Netscape cookies to a managed file on disk."""
    entries = parse_netscape_cookies(content)
    if not entries:
        raise ValueError("No valid Netscape cookies found in the provided text.")

    target_dir = cookies_dir or default_config.cookies_dir
    target_dir.mkdir(parents=True, exist_ok=True)

    clean_dom = sanitize_domain_for_filename(domain)
    profile_id = str(uuid.uuid4())
    filename = f"{clean_dom}_{profile_id[:8]}.txt"
    file_path = target_dir / filename

    formatted_text = format_netscape_cookies(entries)
    file_path.write_text(formatted_text, encoding="utf-8")

    profile = CookieProfileRecord(
        id=profile_id,
        domain=domain.lower().lstrip("."),
        browser_source=browser_source or "text",
        cookie_file_path=str(file_path),
        cookie_count=len(entries),
    )

    logger.info(
        f"Saved {len(entries)} cookies for domain '{domain}' to {file_path.name}"
    )
    return profile, entries


def import_cookies_file(
    file_path: Path | str,
    domain_hint: str | None = None,
    cookies_dir: Path | None = None,
) -> tuple[CookieProfileRecord, list[CookieEntry]]:
    """Import an existing Netscape cookie file from disk into managed storage."""
    src = Path(file_path)
    if not src.exists() or not src.is_file():
        raise FileNotFoundError(f"Cookie file not found: {src}")

    content = src.read_text(encoding="utf-8", errors="replace")
    entries = parse_netscape_cookies(content)
    if not entries:
        raise ValueError(f"No valid cookies found in file: {src.name}")

    if domain_hint:
        domain = domain_hint
    else:
        # Infer domain by most frequent occurrence
        domain_counts: dict[str, int] = {}
        for c in entries:
            dom = c.domain.lstrip(".").lower()
            domain_counts[dom] = domain_counts.get(dom, 0) + 1
        domain = max(domain_counts, key=domain_counts.get) if domain_counts else "all"

    return save_cookies_text(
        domain=domain,
        content=content,
        browser_source="file",
        cookies_dir=cookies_dir,
    )


def extract_browser_cookies(
    browser_name: str,
    domain_filter: str | None = None,
    cookies_dir: Path | None = None,
) -> tuple[CookieProfileRecord, list[CookieEntry]]:
    """Extract cookies from an installed local browser profile via yt-dlp cookie engine."""
    b_name = browser_name.lower().strip()
    if b_name not in SUPPORTED_BROWSERS:
        raise ValueError(
            f"Unsupported browser '{browser_name}'. Supported: {', '.join(SUPPORTED_BROWSERS)}"
        )

    try:
        from yt_dlp.cookies import extract_cookies_from_browser
    except ImportError as err:
        raise RuntimeError("yt-dlp cookie extraction module is not available.") from err

    logger.info(f"Extracting cookies from local browser '{b_name}'...")
    try:
        jar = extract_cookies_from_browser(b_name)
    except Exception as exc:
        logger.error(f"Failed to extract cookies from {b_name}: {exc}")
        raise RuntimeError(
            f"Could not extract cookies from {browser_name}. Ensure the browser is closed: {exc}"
        ) from exc

    entries: list[CookieEntry] = []
    filter_norm = domain_filter.lower().lstrip(".") if domain_filter else None

    for c in jar:
        dom = c.domain.lower()
        if filter_norm and filter_norm not in dom:
            continue

        entries.append(
            CookieEntry(
                domain=c.domain,
                flag=bool(c.domain.startswith(".")),
                path=c.path or "/",
                secure=bool(c.secure),
                expiration=int(c.expires) if c.expires else 0,
                name=c.name,
                value=c.value or "",
            )
        )

    if not entries:
        msg = (
            f"No cookies found in {browser_name} for domain '{domain_filter}'."
            if domain_filter
            else f"No cookies found in {browser_name}."
        )
        raise ValueError(msg)

    primary_domain = filter_norm or (
        entries[0].domain.lstrip(".").lower() if entries else "browser"
    )

    content = format_netscape_cookies(entries)
    return save_cookies_text(
        domain=primary_domain,
        content=content,
        browser_source=b_name,
        cookies_dir=cookies_dir,
    )


def get_cookies_dict_from_file(file_path: Path | str) -> dict[str, str]:
    """Parse a stored cookie file and return a dictionary of {name: value} for HTTP requests."""
    p = Path(file_path)
    if not p.exists() or not p.is_file():
        return {}

    try:
        content = p.read_text(encoding="utf-8", errors="replace")
        entries = parse_netscape_cookies(content)
        return {c.name: c.value for c in entries}
    except Exception as exc:
        logger.warning(f"Failed to read cookies from {p}: {exc}")
        return {}


def list_supported_browsers() -> list[str]:
    """Return the list of browser names supported for automatic cookie extraction."""
    return list(SUPPORTED_BROWSERS)
